  // The user deleted the authorization + x-old lines and typed one new header.
  await h.send({ type: 'provider.save', baseUrl: 'https://a/v1', apiKey: '[REDACTED:Sensitive-Value]', model: 'm', headers: 'x-new: yes' });
  assert.deepEqual(
